python -c "
import urllib.request,re
for idx in ['https://download.pytorch.org/whl/cpu/torch/','https://download.pytorch.org/whl/torch/']:
    try:
        h=urllib.request.urlopen(idx,timeout=30).read().decode('utf-8','ignore')
        arm=sorted(set(re.findall(r'torch-[\d\.]+[^\"<>]*win_arm64[^\"<>]*\.whl',h)))
        print(idx,'->',len(arm),'win_arm64 wheels')
        for a in arm[-12:]: print('   ',a)
    except Exception as e:
        print(idx,'ERR',e)
"
